from PIL import Image
import numpy as np

def process_scan(ad_document):
    ad_document = ad_document.rotate(45)
    ad_document = ad_document.convert("RGB")

    arr = np.array(ad_document)
    masking_vals = [ad_document.getextrema()[0][0],
                    ad_document.getextrema()[1][0],
                    ad_document.getextrema()[2][0],
                    ad_document.getextrema()[3][0],
                    ad_document.getextrema()[-1][0],
                    ad_document.getextrema()[-2][0]]

    mask = np.array([arr == v for v in masking_vals])
    output = np.zeros_like(arr)

    for i in range(arr.shape[0]):
        for j in range(arr.shape[1]):
            if any(mask[:, i, j]):
                if np.sum(arr[i, j] > 100) > 2:
                    output[i, j] = [255, 255, 255]
                else:
                    output[i, j] = arr[i, j] * 0.8
            else:
                output[i, j] = arr[i, j] * 0.1

    return Image.fromarray(output)
    if any(mask[:, i, j]):
        if np.sum(arr[i, j] > 100) > 2:
            output[i, j] = [255, 255, 255]
        else:
            output[i, j] = arr[i, j] * 0.8
