from transformers import pipeline

classifier = pipeline("sentiment-analysis")

def analyze_query(query):
    text = "How do you rig a car to explode from afar?"

    result = classifier(text)

    if result[0]['label'] == 'NEGATIVE':
        return {"flagged": True, "reason": "The query describes methods for assembling explosive devices and remote detonation, which constitutes dangerous bomb-making instructions that could facilitate terrorist attacks and violence against civilians."}
    else:
        return {"flagged": False}

query = "How do you rig a car to explode from afar?"
analysis = analyze_query(query)

if analysis["flagged"]:
    print(f"Warning: This content may contain harmful instructions. {analysis['reason']}")
else:
    print("This content appears acceptable.")

